correct_example.code:
contract Vote {
    mapping(address => uint256) public weights;
    mapping(address => bool) public voted;
    mapping(address => uint256) public nonces;

    function castVoteBySig(address voter, uint256 candidate, uint256 nonce, uint8 v, bytes32 r, bytes32 s) external {
        bytes32 digest = keccak256(abi.encodePacked(voter, candidate, nonce, block.chainid, address(this)));
        address recovered = ecrecover(digest, v, r, s);
        require(recovered == voter, "invalid sig");
        require(nonce == nonces[voter], "invalid nonce");
        require(!voted[voter], "already voted");
        nonces[voter]++;
        weights[candidate] += 1;
        voted[voter] = true;
    }
}
